#define _POSIX_C_SOURCE 200809L
#include "database.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <sys/stat.h>
#include <errno.h>
#include <time.h>

#define DATA_FILE "bank_data.txt"
#define LOCK_FILE "bank.lock"
#define TEMP_FILE "bank_data.tmp"
#define MAX_RECORDS 4000
#define RECORD_SIZE 1024

typedef struct { int fd; } DbLock;
static int lock_data(DbLock *l) { l->fd=open(LOCK_FILE,O_CREAT|O_RDWR,0600); if(l->fd<0)return -1; while(flock(l->fd,LOCK_EX)<0){if(errno==EINTR)continue;close(l->fd);return -1;} return 0; }
static void unlock_data(DbLock *l) { if(l->fd>=0){flock(l->fd,LOCK_UN);close(l->fd);l->fd=-1;} }
static int load_data(char (*lines)[RECORD_SIZE], size_t *n) { FILE *f=fopen(DATA_FILE,"r"); *n=0; if(!f)return errno==ENOENT?0:-1; char buf[RECORD_SIZE]; while(fgets(buf,sizeof buf,f)){size_t z=strlen(buf);if(z&&buf[z-1]=='\n')buf[--z]='\0';if(z&&buf[z-1]=='\r')buf[--z]='\0';if(*n>=MAX_RECORDS){fclose(f);return -1;}snprintf(lines[(*n)++],RECORD_SIZE,"%s",buf);} int bad=ferror(f);fclose(f);return bad?-1:0; }
static int save_data(char (*lines)[RECORD_SIZE], size_t n) { int fd=open(TEMP_FILE,O_CREAT|O_TRUNC|O_WRONLY,0600);if(fd<0)return -1;FILE *f=fdopen(fd,"w");if(!f){close(fd);return -1;}for(size_t i=0;i<n;i++)if(fprintf(f,"%s\n",lines[i])<0){fclose(f);return -1;}if(fflush(f)!=0||fsync(fileno(f))!=0){fclose(f);return -1;}if(fclose(f)!=0)return -1;if(rename(TEMP_FILE,DATA_FILE)!=0)return -1;int d=open(".",O_RDONLY);if(d>=0){fsync(d);close(d);}return 0; }
static size_t split_fields(char *s,char **f,size_t cap){size_t n=0;if(!cap)return 0;f[n++]=s;for(char *p=s;*p;p++)if(*p=='|'&&n<cap){*p='\0';f[n++]=p+1;}return n;}
static int parse_int(const char *s,int *v){char *e=NULL;long x=strtol(s,&e,10);if(!s||!*s||!e||*e||x<0||x>2147483647L)return -1;*v=(int)x;return 0;}
static int user_by_id(char (*lines)[RECORD_SIZE],size_t n,int id,char **fields,size_t *nf,char *copy){for(size_t i=0;i<n;i++){if(strncmp(lines[i],"USER|",5)!=0)continue;snprintf(copy,RECORD_SIZE,"%s",lines[i]);size_t k=split_fields(copy,fields,12);int x;if(k>=7&&parse_int(fields[1],&x)==0&&x==id){*nf=k;return (int)i;}}return -1;}
static int role_of_user(char (*lines)[RECORD_SIZE],size_t n,int id,int want_role,int require_active){char *f[12],copy[RECORD_SIZE];size_t nf=0;int ix=user_by_id(lines,n,id,f,&nf,copy);if(ix<0||nf<7)return 0;int role,active;if(parse_int(f[4],&role)||parse_int(f[5],&active))return 0;return role==want_role&&(!require_active||active==1);}
static void append_text(char *buf,size_t cap,const char *s){size_t n=strlen(buf);if(n+1<cap)snprintf(buf+n,cap-n,"%s",s);}

int mgmt_list_assigned_loans(int employee_id,char *buffer,size_t cap){if(!buffer||cap<2)return -1;buffer[0]=0;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;char out[400]="Assigned loans: ";int count=0;for(size_t i=0;i<n;i++){if(strncmp(lines[i],"LOAN|",5))continue;char c[RECORD_SIZE];snprintf(c,sizeof c,"%s",lines[i]);char *f[12];size_t nf=split_fields(c,f,12);int emp=0;if(nf>=8&&parse_int(f[6],&emp)==0&&emp==employee_id){char item[180];snprintf(item,sizeof item,"%sloan=%s customer=%s amount_paise=%s status=%s purpose=%.40s",count?"; ":"",f[1],f[2],f[3],f[5],f[4]);append_text(out,sizeof out,item);count++;}}if(!count)snprintf(out,sizeof out,"No loans assigned");snprintf(buffer,cap,"%s",out);rc=0;done:free(lines);unlock_data(&l);return rc;}

int mgmt_process_loan(int employee_id,long long loan_id,const char *decision){if(loan_id<=0||!decision||(strcmp(decision,"APPROVE")&&strcmp(decision,"REJECT")))return -1;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;for(size_t i=0;i<n;i++){if(strncmp(lines[i],"LOAN|",5))continue;char c[RECORD_SIZE];snprintf(c,sizeof c,"%s",lines[i]);char *f[12];size_t nf=split_fields(c,f,12);long long id=atoll(nf>1?f[1]:"0");int emp=0;if(id!=loan_id)continue;if(nf<8||parse_int(f[6],&emp)||emp!=employee_id){rc=-3;goto done;}if(strcmp(f[5],"PENDING")){rc=-2;goto done;}char ts[64];snprintf(ts,sizeof ts,"%s",f[7]);snprintf(lines[i],RECORD_SIZE,"LOAN|%s|%s|%s|%s|%s|%s|%s",f[1],f[2],f[3],f[4],decision, f[6],ts);rc=save_data(lines,n)==0?0:-1;goto done;}rc=-3;done:free(lines);unlock_data(&l);return rc;}

int db_list_pending_loans(char *buffer,size_t cap){if(!buffer||cap<2)return -1;buffer[0]=0;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;char out[450]="Pending loans: ";int count=0;for(size_t i=0;i<n;i++){if(strncmp(lines[i],"LOAN|",5))continue;char c[RECORD_SIZE];snprintf(c,sizeof c,"%s",lines[i]);char *f[12];size_t nf=split_fields(c,f,12);int assigned=0;if(nf<7||strcmp(f[5],"PENDING"))continue;if(nf>=8)parse_int(f[6],&assigned);if(assigned!=0)continue;char item[160];snprintf(item,sizeof item,"%sloan=%s customer=%s amount_paise=%s purpose=%.35s",count?"; ":"",f[1],f[2],f[3],f[4]);append_text(out,sizeof out,item);count++;}if(!count)snprintf(out,sizeof out,"No unassigned pending loans");snprintf(buffer,cap,"%s",out);rc=0;done:free(lines);unlock_data(&l);return rc;}

int db_assign_loan(int manager_id,long long loan_id,int employee_id){if(loan_id<=0||employee_id<=0)return -1;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;if(!role_of_user(lines,n,manager_id,3,1)){rc=-1;goto done;}if(!role_of_user(lines,n,employee_id,2,1)){rc=-2;goto done;}for(size_t i=0;i<n;i++){if(strncmp(lines[i],"LOAN|",5))continue;char c[RECORD_SIZE];snprintf(c,sizeof c,"%s",lines[i]);char *f[12];size_t nf=split_fields(c,f,12);if(nf<7||atoll(f[1])!=loan_id)continue;int assigned=0;if(nf>=8)parse_int(f[6],&assigned);if(strcmp(f[5],"PENDING")||assigned!=0){rc=-3;goto done;}char timestamp[128];snprintf(timestamp,sizeof timestamp,"%s",nf>=8?f[7]:f[6]);snprintf(lines[i],RECORD_SIZE,"LOAN|%s|%s|%s|%s|%s|%d|%s",f[1],f[2],f[3],f[4],f[5],employee_id,timestamp);rc=save_data(lines,n)==0?0:-1;goto done;}rc=-3;done:free(lines);unlock_data(&l);return rc;}

int db_manager_set_customer_active(int manager_id,int customer_id,int active){if(customer_id<=0||(active!=0&&active!=1))return -1;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;if(!role_of_user(lines,n,manager_id,3,1)){rc=-1;goto done;}char c[RECORD_SIZE],*f[12];size_t nf=0;int ix=user_by_id(lines,n,customer_id,f,&nf,c);if(ix<0){rc=-2;goto done;}int role;if(nf<7||parse_int(f[4],&role)||role!=1){rc=-3;goto done;}snprintf(lines[ix],RECORD_SIZE,"USER|%s|%s|%s|%s|%d|%s",f[1],f[2],f[3],f[4],active,f[6]);rc=save_data(lines,n)==0?0:-1;done:free(lines);unlock_data(&l);return rc;}

int db_list_feedback(char *buffer,size_t cap){if(!buffer||cap<2)return -1;buffer[0]=0;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;char out[450]="Feedback: ";int count=0;for(size_t i=0;i<n;i++){if(strncmp(lines[i],"FEEDBACK|",9))continue;char item[180];snprintf(item,sizeof item,"%s%.150s",count?"; ":"",lines[i]+9);append_text(out,sizeof out,item);count++;}if(!count)snprintf(out,sizeof out,"No feedback submitted");snprintf(buffer,cap,"%s",out);rc=0;done:free(lines);unlock_data(&l);return rc;}

int db_admin_create_employee(int admin_id,const char *username,const char *password,int *new_id){if(!username||!password||!*username||!*password||strchr(username,'|')||strchr(password,'|')||strchr(username,' ')||strchr(password,' ')||!new_id)return -1;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;if(!role_of_user(lines,n,admin_id,4,1)){rc=-1;goto done;}int maxid=0;for(size_t i=0;i<n;i++){if(strncmp(lines[i],"USER|",5))continue;char c[RECORD_SIZE];snprintf(c,sizeof c,"%s",lines[i]);char *f[12];size_t nf=split_fields(c,f,12);if(nf<7)continue;if(!strcmp(f[2],username)){rc=-2;goto done;}int id;if(!parse_int(f[1],&id)&&id>maxid)maxid=id;}if(n>=MAX_RECORDS){rc=-1;goto done;}*new_id=maxid+1;snprintf(lines[n++],RECORD_SIZE,"USER|%d|%s|%s|2|1|0",*new_id,username,password);rc=save_data(lines,n)==0?0:-1;done:free(lines);unlock_data(&l);return rc;}

int db_admin_edit_user(int admin_id,int user_id,const char *username,const char *password,int role,int active){if(user_id<=0||!username||!password||!*username||!*password||strchr(username,'|')||strchr(password,'|')||strchr(username,' ')||strchr(password,' ')||role<1||role>4||(active!=0&&active!=1))return -1;DbLock l={-1};if(lock_data(&l))return -1;char (*lines)[RECORD_SIZE]=calloc(MAX_RECORDS,RECORD_SIZE);size_t n=0;int rc=-1;if(!lines||load_data(lines,&n))goto done;if(!role_of_user(lines,n,admin_id,4,1)||admin_id==user_id){rc=-1;goto done;}char c[RECORD_SIZE],*f[12];size_t nf=0;int ix=user_by_id(lines,n,user_id,f,&nf,c);if(ix<0||nf<7){rc=-2;goto done;}for(size_t i=0;i<n;i++){if(i== (size_t)ix||strncmp(lines[i],"USER|",5))continue;char cc[RECORD_SIZE];snprintf(cc,sizeof cc,"%s",lines[i]);char *ff[12];size_t nn=split_fields(cc,ff,12);if(nn>=3&&!strcmp(ff[2],username)){rc=-3;goto done;}}snprintf(lines[ix],RECORD_SIZE,"USER|%s|%s|%s|%d|%d|%s",f[1],username,password,role,active,f[6]);rc=save_data(lines,n)==0?0:-1;done:free(lines);unlock_data(&l);return rc;}
